"use strict";
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)], money=n=>`₹${Number(n||0).toLocaleString("en-IN")}`;
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);
const imgSafe=s=>String(s||"").startsWith("/uploads/")||/^https:\/\//.test(String(s||""))?String(s):"/assets/product-placeholder.svg";
const im=(s,a="",c="")=>`<img class="${c}" src="${esc(imgSafe(s))}" alt="${esc(a)}" loading="lazy">`;
const STAR='<span class="stars">★★★★★</span>', STATUSES=["Order Received","Confirmed","Processing","Shipped","Out for Delivery","Delivered","Cancelled"], app=$("#app");
const S={products:[],categories:[],settings:{shop_name:"AMORA MART",delivery_charge:49,free_delivery_threshold:999},draft:{},csrf:"",admin:false,view:"dashboard",ad:{},filter:"All",search:"",sort:"popular",filters:{category:"All",min:"",max:"",discount:false,available:true,rating:0},fav:new Set(JSON.parse(localStorage.getItem("amora_favorites")||"[]")),selected:null,variant:"",qty:1};
const readCart=()=>{try{return JSON.parse(localStorage.getItem("amora_cart")||"[]")}catch{return[]}}, tokens=()=>{try{return JSON.parse(localStorage.getItem("amora_orders")||"[]")}catch{return[]}};
function badge(){let n=readCart().reduce((a,x)=>a+Number(x.quantity||0),0);[ $("#cart-count"),$("#mobile-cart-count")].forEach(e=>{if(e)e.textContent=n>99?"99+":n})}
function toast(msg,error=false){let e=$("#toast");if(!e)return;e.textContent=msg;e.classList.toggle("error",error);e.classList.add("show");clearTimeout(window._toast);window._toast=setTimeout(()=>e.classList.remove("show"),2600)}
async function api(url,opt={}){let h={...(opt.body?{"Content-Type":"application/json"}:{}),...(opt.headers||{})};if(opt.write&&S.csrf)h["X-CSRF-Token"]=S.csrf;let r=await fetch(url,{...opt,headers:h,credentials:"same-origin"}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Something went wrong. Please try again.");return d}
function go(url,replace=false){let u=new URL(url,location.origin);history[replace?"replaceState":"pushState"]({},"",u.pathname+u.search+u.hash);render();if(u.hash)setTimeout(()=>$(u.hash)?.scrollIntoView({behavior:"smooth"}),80);else scrollTo({top:0,behavior:"smooth"})}
const path=()=>location.pathname.replace(/\/$/,"")||"/", prod=id=>S.products.find(p=>+p.id===+id), resolved=()=>readCart().map(x=>({...x,p:prod(x.product_id)})).filter(x=>x.p);
function totals(lines=resolved()){let sub=lines.reduce((n,x)=>n+x.p.price*x.quantity,0),mrp=lines.reduce((n,x)=>n+x.p.mrp*x.quantity,0),ship=!sub||sub>=S.settings.free_delivery_threshold?0:S.settings.delivery_charge;return{sub,discount:Math.max(0,mrp-sub),ship,total:sub+ship}}
function setCart(c){localStorage.setItem("amora_cart",JSON.stringify(c));badge()}
function add(p,v,q=1){if(!p||p.stock_status!=="in_stock"){toast("This find is currently unavailable.",true);return}let c=readCart(),line=c.find(x=>+x.product_id===+p.id&&x.variant===(v||p.variants?.[0]||"Standard"));if(line)line.quantity=Math.min(20,line.quantity+q);else c.push({product_id:p.id,variant:v||p.variants?.[0]||"Standard",quantity:q});setCart(c);toast(`${p.name} added to your bag.`)}
function stars(){return STAR} function status(s){let cl=s.toLowerCase().replaceAll(" ","-");return `<span class="table-status status-${esc(cl)}">${esc(s)}</span>`}
function crumb(items){return `<div class="breadcrumb"><a href="/" data-link="/">Home</a>${items.map((x,i)=>`<span>›</span>${i===items.length-1?`<span>${esc(x)}</span>`:`<a href="/shop" data-link="/shop">${esc(x)}</a>`}`).join("")}</div>`}
function head(k,t,d="",link=""){return `<div class="section-head"><div><span class="section-kicker">${esc(k)}</span><h2>${esc(t)}</h2>${d?`<p>${esc(d)}</p>`:""}</div>${link?`<a class="text-link" href="/shop" data-link="/shop">${esc(link)} <span>↗</span></a>`:""}</div>`}
function card(p,b=""){let discount=p.discount||0,tag=p.is_demo?"Demo sample":b||(p.featured?"A little favourite":p.bestseller?"Best seller":discount?`${discount}% off`:"");let review=p.reviews?`${stars()} <span>${Number(p.rating).toFixed(1)} (${p.reviews})</span>`:`<span>No reviews yet</span>`;return `<article class="product-card"><a class="product-image" href="/product/${encodeURIComponent(p.slug)}" data-link="/product/${encodeURIComponent(p.slug)}">${im(p.images?.[0],p.name)}${tag?`<span class="product-badge ${discount?"sale":""}">${esc(tag)}</span>`:""}</a><button class="product-heart ${S.fav.has(String(p.id))?"active":""}" data-action="fav" data-id="${p.id}">${S.fav.has(String(p.id))?"♥":"♡"}</button><div class="product-info"><div class="product-category">${esc(p.category)}</div><a href="/product/${encodeURIComponent(p.slug)}" data-link="/product/${encodeURIComponent(p.slug)}"><h3 class="product-title">${esc(p.name)}</h3></a><div class="product-rating">${review}</div><div class="product-price-row"><strong class="product-price">${money(p.price)}</strong>${p.mrp>p.price?`<s class="product-mrp">${money(p.mrp)}</s><span class="product-off">${discount}% off</span>`:""}</div><div class="cod-label">✓ Cash on Delivery available</div><div class="product-actions"><button class="btn btn-outline" data-action="add" data-id="${p.id}">Add to bag</button><button class="btn btn-primary" data-action="buy" data-id="${p.id}">Buy now</button></div></div></article>`}
function trust(){return `<div class="trust-row">${[["⌂","Everyday finds","Useful finds for less"],["₹","Easy-on-budget prices","More value for your money"],["▣","Pay on delivery","Cash on Delivery available"],["♡","Here to help","Friendly customer support"]].map(x=>`<div class="trust-item"><span class="trust-icon">${x[0]}</span><span><strong>${x[1]}</strong><small>${x[2]}</small></span></div>`).join("")}</div>`}
function home(){let cats=S.categories.slice(0,5),featured=S.products.filter(x=>x.featured).slice(0,4),best=S.products.filter(x=>x.bestseller).slice(0,4),deals=[...S.products].sort((a,b)=>b.discount-a.discount).slice(0,4),fresh=[...S.products].sort((a,b)=>b.id-a.id).slice(0,4);return `<section class="hero"><div class="hero-copy"><span class="eyebrow"><i class="eyebrow-mark"></i> SMART FINDS. SMALL PRICES.</span><h1>Smart finds.<br><em>Happier prices.</em><br>Every day.</h1><p>Discover handy everyday essentials and budget-friendly finds for home, kitchen, and life.</p><div class="hero-buttons"><a class="btn btn-primary" href="/shop" data-link="/shop">Shop affordable finds ↗</a><a class="btn btn-outline" href="/#deals" data-link="/#deals">See low-price deals</a></div><div class="hero-note"><span><i class="hero-check">✓</i> Cash on Delivery</span><span><i class="hero-check">✓</i> Easy online ordering</span></div></div><div class="hero-art"><img src="/uploads/shoe-rack-main.webp" alt="Portable shoe storage rack for an organized home" fetchpriority="high"><div class="hero-floating">Little things. Big delight.<strong>Find your <span>favourite.</span></strong></div></div></section><section class="section" id="categories">${head("A GOOD PLACE TO START","Shop by category","Shop useful everyday products at prices that make sense.","Browse everything")}<div class="categories-grid">${cats.map(c=>`<a class="category-tile" href="/shop?category=${encodeURIComponent(c.name)}" data-link="/shop?category=${encodeURIComponent(c.name)}"><div class="category-photo">${im(c.image,c.name)}</div><div class="category-info"><span class="category-arrow">↗</span><strong>${esc(c.name)}</strong><span>${esc(c.description||"A few good things to find")}</span></div></a>`).join("")}</div></section><section class="section">${head("GOOD VALUE, HAND-PICKED","Trending right now","Popular everyday finds with prices worth a look.","Shop all finds")}<div class="product-grid">${(featured.length?featured:S.products.slice(0,4)).map(p=>card(p,"Trending")).join("")}</div></section><section class="promo-strip"><div class="promo-left"><span class="eyebrow">A LITTLE MORE FOR YOUR MONEY</span><h2>More for less, under ₹699</h2><p>Useful everyday picks at wallet-friendly prices.</p></div><a class="promo-sticker" href="/shop?max=699" data-link="/shop?max=699"><strong>₹699</strong><span>and under ↗</span></a></section><section id="deals" class="section">${head("WORTH A LITTLE LOOK","Today’s best-value deals","Useful finds at even better prices.","See all deals")}<div class="product-grid">${deals.map(p=>card(p,"Lovely deal")).join("")}</div></section><section class="section">${head("GOOD VALUE, LOVED BY SHOPPERS","Popular budget-friendly picks","Useful, thoughtful things worth coming back for.","Meet the best sellers")}<div class="product-grid">${(best.length?best:S.products.slice(0,4)).map(p=>card(p,"Best seller")).join("")}</div></section><section class="section">${head("NEW FINDS, FRIENDLY PRICES","New little arrivals","New everyday finds at prices that feel good.","See what’s new")}<div class="product-grid">${fresh.map(p=>card(p,"Just in")).join("")}</div></section>${trust()}`}

function listing(){let pms=new URLSearchParams(location.search),q=(pms.get("q")||"").trim(),cat=pms.get("category")||"All",min=Number(pms.get("min")||0),max=Number(pms.get("max")||0),deal=pms.get("deal")==="1",rating=Number(pms.get("rating")||0),sort=pms.get("sort")||"popular";S.filters.category=cat;let items=S.products.filter(p=>(!q||`${p.name} ${p.category} ${p.description} ${(p.variants||[]).join(" ")}`.toLowerCase().includes(q.toLowerCase()))&&(cat==="All"||p.category===cat)&&(!min||p.price>=min)&&(!max||p.price<=max)&&(!deal||p.discount>0)&&(!rating||p.rating>=rating)&&(!S.filters.available||p.stock_status==="in_stock"));if(sort==="price-asc")items.sort((a,b)=>a.price-b.price);else if(sort==="price-desc")items.sort((a,b)=>b.price-a.price);else if(sort==="discount")items.sort((a,b)=>b.discount-a.discount);else if(sort==="newest")items.sort((a,b)=>b.id-a.id);else items.sort((a,b)=>b.bestseller-a.bestseller||b.rating-a.rating);let choices=S.categories.map(c=>`<label class="filter-option"><input type="radio" name="category" value="${esc(c.name)}" ${cat===c.name?"checked":""}> ${esc(c.name)}</label>`).join("");return `${crumb(["Shop all finds"])}<div class="catalog-heading"><div><h1>${q?"Search results":cat==="All"?"All the lovely finds":esc(cat)}</h1><p>${q?`For “${esc(q)}” · `:""}Little things for everyday living, all in one place.</p></div><button class="btn btn-outline btn-small mobile-filter" data-action="toggle-filter">☷ &nbsp; Filters</button></div><div class="catalog-layout"><aside class="filter-panel" id="filter-panel"><div class="filter-head">Filters <button data-action="clear">Clear all</button></div><div class="filter-group"><h3>Category</h3><label class="filter-option"><input type="radio" name="category" value="All" ${cat==="All"?"checked":""}> All finds</label>${choices}</div><div class="filter-group"><h3>Your budget</h3><div class="filter-price"><input id="min-price" type="number" placeholder="Min ₹" value="${min||""}"><span>–</span><input id="max-price" type="number" placeholder="Max ₹" value="${max||""}"></div></div><div class="filter-group"><h3>Special picks</h3><label class="filter-option"><input type="checkbox" id="discount-only" ${deal?"checked":""}> On sale</label><label class="filter-option"><input type="checkbox" id="available-only" ${S.filters.available?"checked":""}> Available now</label></div><div class="filter-group"><h3>Customer rating</h3>${[[0,"Any rating"],[4,"4 stars & up"],[4.5,"4.5 stars & up"]].map(([n,label])=>`<label class="filter-option"><input type="radio" name="rating" value="${n}" ${rating===n?"checked":""}> ${label}</label>`).join("")}</div><button class="btn btn-primary btn-small" style="width:100%" data-action="apply">Show finds</button></aside><div><div class="results-toolbar"><p><strong>${items.length}</strong> lovely ${items.length===1?"find":"finds"}</p><select class="sort-select" id="sort-products"><option value="popular" ${sort==="popular"?"selected":""}>Popular</option><option value="newest" ${sort==="newest"?"selected":""}>Newest</option><option value="price-asc" ${sort==="price-asc"?"selected":""}>Price: low to high</option><option value="price-desc" ${sort==="price-desc"?"selected":""}>Price: high to low</option><option value="discount" ${sort==="discount"?"selected":""}>Highest discount</option></select></div>${items.length?`<div class="product-grid">${items.map(p=>card(p)).join("")}</div>`:`<div class="empty-state"><div class="empty-icon">⌕</div><h2>No finds just yet</h2><p>Try another search or clear a filter to see what else you might love.</p><button class="btn btn-primary" data-action="clear">See all affordable finds</button></div>`}</div></div>`}

function productPage(slug){let p=S.products.find(x=>x.slug===slug);if(!p)return `${crumb(["Product"])}<div class="empty-state"><div class="empty-icon">⌕</div><h2>We couldn’t find that one</h2><p>This find may have moved on.</p><a class="btn btn-primary" href="/shop" data-link="/shop">Browse all finds</a></div>`;S.selected=p;S.qty=1;S.variant=p.variants?.[0]||"Standard";return `${crumb([p.category,p.name])}<section class="detail-layout"><div><div class="detail-main-image" id="detail-image">${im(p.images?.[0],p.name)}</div><div class="detail-thumbs">${(p.images||[]).map((s,i)=>`<button class="detail-thumb ${i===0?"selected":""}" data-action="image" data-src="${esc(s)}">${im(s,p.name)}</button>`).join("")}</div></div><div class="detail-info"><span class="product-category">${esc(p.category)}</span><h1>${esc(p.name)}</h1><div class="detail-rating">${p.reviews?`${stars()} <strong>${Number(p.rating).toFixed(1)}</strong><span>${p.reviews} reviews</span>`:`<span>No reviews yet</span>`}</div><div class="detail-price"><strong>${money(p.price)}</strong>${p.mrp>p.price?`<s>${money(p.mrp)}</s><span class="discount-pill">${p.discount}% off</span>`:""}</div><div class="tax-note">Inclusive of all taxes</div><p class="detail-description">${esc(p.description)}</p>${p.is_demo?`<p class="policy-placeholder">Demo sample listing — replace this product information and imagery before launch.</p>`:""}${p.variants?.length?`<div class="detail-subhead">Choose your option</div><div class="variant-options">${p.variants.map((v,i)=>`<button class="variant-option ${i===0?"selected":""}" data-action="variant" data-value="${esc(v)}">${esc(v)}</button>`).join("")}</div>`:""}<div class="detail-subhead">Quantity</div><div class="detail-qty"><div class="qty-stepper"><button data-action="pqty" data-delta="-1">−</button><span id="detail-qty">1</span><button data-action="pqty" data-delta="1">+</button></div><span class="cod-label">${p.stock_status==="in_stock"?"✓ In stock · COD available":"Currently unavailable"}</span></div><div class="delivery-check"><label class="detail-subhead" style="margin:0">Check delivery</label><input id="pin-check" inputmode="numeric" maxlength="6" placeholder="PIN code"><button data-action="pin">Check</button></div><p id="pin-result" class="delivery-result"></p><div class="detail-actions"><button class="btn btn-outline" data-action="dadd" data-id="${p.id}">Add to bag</button><button class="btn btn-primary" data-action="dbuy" data-id="${p.id}">Buy now ↗</button></div><div class="assurance-list"><div class="assurance"><span class="assurance-icon">▣</span>Secure ordering</div><div class="assurance"><span class="assurance-icon">₹</span>COD available</div><div class="assurance"><span class="assurance-icon">♡</span>Easy support</div></div><div class="section" style="margin-top:29px"><div class="detail-subhead">A little more about it</div><ul class="spec-list">${(p.specs||[]).map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div></div></section><section class="section">${head("MORE GOOD THINGS","You might like these too","A few other finds to keep you browsing.","Shop all finds")}<div class="product-grid">${S.products.filter(x=>x.id!==p.id).slice(0,4).map(x=>card(x)).join("")}</div></section>`}

function summary(t){return `<div class="summary-row"><span>Subtotal</span><strong>${money(t.sub)}</strong></div><div class="summary-row"><span>Delivery</span><strong>${t.ship?money(t.ship):"Free"}</strong></div><div class="summary-row discount"><span>You save</span><strong>−${money(t.discount)}</strong></div><div class="summary-row summary-total"><span>Total</span><strong>${money(t.total)}</strong></div>`}
function cartPage(){let lines=resolved(),t=totals(lines);if(!lines.length)return `${crumb(["Your bag"])}<div class="catalog-heading"><div><h1>Your shopping bag</h1><p>Your next little favourite is just around the corner.</p></div></div><div class="empty-state"><div class="empty-icon">♧</div><h2>Your bag is waiting for a great-value find</h2><p>Browse budget-friendly everyday finds and add a little value to your bag.</p><a class="btn btn-primary" href="/shop" data-link="/shop">Browse all finds ↗</a></div>`;return `${crumb(["Your bag"])}<div class="catalog-heading"><div><h1>Your shopping bag</h1><p>${lines.reduce((n,x)=>n+x.quantity,0)} little ${lines.length===1?"find":"finds"}, all in one place.</p></div><a href="/shop" data-link="/shop" class="text-link">Keep browsing ↗</a></div><div class="cart-layout"><div class="cart-items">${lines.map(x=>`<div class="cart-item"><a href="/product/${encodeURIComponent(x.p.slug)}" data-link="/product/${encodeURIComponent(x.p.slug)}">${im(x.p.images?.[0],x.p.name,"cart-item-image")}</a><div><a href="/product/${encodeURIComponent(x.p.slug)}" data-link="/product/${encodeURIComponent(x.p.slug)}"><h3>${esc(x.p.name)}</h3></a><div class="cart-item-meta">Option: ${esc(x.variant)}</div><div class="cart-item-controls"><div class="qty-stepper"><button data-action="cqty" data-id="${x.p.id}" data-v="${esc(x.variant)}" data-d="-1">−</button><span>${x.quantity}</span><button data-action="cqty" data-id="${x.p.id}" data-v="${esc(x.variant)}" data-d="1">+</button></div><button class="cart-remove" data-action="remove" data-id="${x.p.id}" data-v="${esc(x.variant)}">Remove</button></div></div><div class="cart-line-end"><div class="cart-item-price">${money(x.p.price*x.quantity)}</div><small class="cart-item-meta">${money(x.p.price)} each</small></div></div>`).join("")}</div><aside class="cart-summary"><h2>Order summary</h2>${summary(t)}<a href="/checkout" data-link="/checkout" class="btn btn-primary">Proceed to checkout ↗</a><a href="/shop" data-link="/shop" class="btn btn-light">Continue shopping</a><p class="summary-small">Cash on Delivery available · Your details stay private</p></aside></div>`}

function addr(a){return [a.house,a.street,a.locality,a.landmark&&`Near ${a.landmark}`,a.city,a.district,a.state,a.pin].filter(Boolean).join(", ")}
function checkout(){let lines=resolved(),t=totals(lines),d=S.draft;if(!lines.length)return `${crumb(["Checkout"])}<div class="empty-state"><div class="empty-icon">♧</div><h2>Start with your bag</h2><p>Add a few finds before heading to checkout.</p><a class="btn btn-primary" href="/shop" data-link="/shop">Browse all finds</a></div>`;const fields=[ ["full_name","Full name","Name for the delivery","text","name"],["phone","Mobile number","10-digit mobile number","tel","tel"],["alternate_phone","Alternate number · optional","Another contact number","tel","tel-national"],["house","House / building","House or building name","text","address-line1"],["street","Street / area","Street or area","text","address-line2"],["locality","Locality","Locality / neighbourhood","text",""],["landmark","Landmark · optional","A nearby landmark","text",""],["city","City / town","City or town","text","address-level2"],["district","District","District","text",""],["state","State","State","text","address-level1"],["pin","PIN code","6-digit PIN code","text","postal-code"] ];return `${crumb(["Your bag","Checkout"])}<div class="catalog-heading"><div><h1>Almost yours</h1><p>A few delivery details and your finds are on their way.</p></div><span class="status-chip">Secure checkout</span></div><form id="checkout-form" class="checkout-layout"><div class="checkout-main"><section class="checkout-step"><div class="checkout-step-head"><span class="step-number">1</span><div><h2>Where should we send your finds?</h2><small>Your information is visible only to authorised store administrators for fulfilment and support.</small></div></div><div class="form-grid">${fields.map(([key,label,placeholder,type,autocomplete])=>`<div class="form-field ${key==="full_name"?"full":""}"><label for="f-${key}">${label}${!key.includes("alternate")&&!key.includes("landmark")?" *":""}</label><input id="f-${key}" name="${key}" type="${type}" ${!key.includes("alternate")&&!key.includes("landmark")?"required":""} ${autocomplete?`autocomplete="${autocomplete}"`:""} maxlength="150" ${key==="pin"?`inputmode="numeric" pattern="[0-9]{6}"`:""} ${key==="phone"?`inputmode="tel" pattern="(?:\\+91[\\s-]?)?[6-9][0-9\\s-]{8,14}"`:""} placeholder="${placeholder}" value="${esc(d[key]||"")}"></div>`).join("")}</div></section><section class="checkout-step"><div class="checkout-step-head"><span class="step-number">2</span><div><h2>How would you like to pay?</h2><small>Choose what works for you.</small></div></div><label class="payment-option"><input type="radio" name="payment_method" value="COD" checked><span><strong>Cash on Delivery</strong><small>Pay when your order is delivered.</small></span></label><label class="payment-disabled"><input type="radio" disabled><span><strong style="font-size:11px">Online payment</strong><small>Coming soon — available after secure payment setup.</small></span></label></section></div><aside class="cart-summary checkout-summary-panel"><h2>Your order</h2><div class="checkout-items">${lines.map(x=>`<div class="checkout-item">${im(x.p.images?.[0],x.p.name)}<div><strong>${esc(x.p.name)}</strong><small>${esc(x.variant)} · Qty ${x.quantity}</small></div><b>${money(x.p.price*x.quantity)}</b></div>`).join("")}</div>${summary(t)}<div id="review-preview"></div><label class="review-confirm"><input id="confirm-details" type="checkbox" required><span>I confirm that my delivery details are correct.</span></label><button class="btn btn-primary place-order" id="place-order">Place order ↗</button><p class="secure-note">🔒 Secure ordering · Payment collected on delivery</p><p id="checkout-error" class="admin-inline-error" role="alert"></p></aside></form>`}
function preview(){let form=$("#checkout-form");if(!form)return;let d=Object.fromEntries(new FormData(form).entries());Object.assign(S.draft,d);let box=$("#review-preview");if(!box||!(d.full_name||d.phone||d.house)){if(box)box.innerHTML="";return}let a={house:d.house,street:d.street,locality:d.locality,landmark:d.landmark,city:d.city,district:d.district,state:d.state,pin:d.pin};box.innerHTML=`<div class="summary-row" style="display:block;border-top:1px solid var(--line);padding-top:12px"><span style="display:block;font-size:9px;text-transform:uppercase;letter-spacing:.1em;color:#8b968d;margin-bottom:5px">Delivering to</span><strong style="display:block">${esc(d.full_name||"Your name")}</strong><span style="display:block;margin-top:3px">${esc(d.phone||"Mobile number")}</span><span style="display:block;line-height:1.7;margin-top:4px">${esc(addr(a)||"Your delivery address")}</span><span style="display:block;margin-top:5px;color:#3978ce;font-size:9px">Payment: Cash on Delivery</span></div>`}
function confirmation(o,id){return `${crumb(["Order received"])}<section class="order-success"><div class="success-mark">✓</div><h1>Order confirmed!</h1><p>Thank you, ${esc(o.full_name)}. We’ve received your order and will keep you posted.</p><div class="order-reference"><span>ORDER REFERENCE</span><strong>${esc(o.order_id||id)}</strong>${status(o.status)}</div><div class="order-detail-card"><div class="order-block"><h3>Your finds</h3>${(o.items||[]).map(i=>`<div class="order-product">${im(i.image,i.product_name)}<span><strong>${esc(i.product_name)}</strong><small>${esc(i.variant)} · Qty ${i.quantity} · ${money(i.price*i.quantity)}</small></span></div>`).join("")}<div class="summary-row summary-total"><span>Order total</span><strong>${money(o.total)}</strong></div></div><div class="order-block"><h3>Payment</h3><p>Cash on Delivery<br>Pay when your order is delivered.<br><br>Payment status: ${esc(o.payment_status)}</p></div><div class="order-block"><h3>Delivery details</h3><p><strong>${esc(o.full_name)}</strong><br>${esc(o.phone)}<br>${esc(addr(o.address||{}))}</p></div><div class="order-block"><h3>Order details</h3><p>Placed ${esc(new Date(o.created_at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"}))}<br>Status: ${esc(o.status)}<br>Delivery: ${o.shipping?money(o.shipping):"Free"}</p></div></div><div class="confirmation-actions"><a class="btn btn-outline" href="/track/${encodeURIComponent(o.order_id||id)}" data-link="/track/${encodeURIComponent(o.order_id||id)}">Track my order</a><a class="btn btn-primary" href="/shop" data-link="/shop">Continue shopping ↗</a></div></section>`}
function trackingLookup(id="",error=""){return `${crumb(["Track an order"])}<section class="tracking-panel"><span class="section-kicker">ORDER UPDATES</span><h1>Track your order</h1><p>Enter the order ID from your confirmation and the mobile number used at checkout.</p><form id="track-form" class="tracking-form"><div class="form-field"><label for="track-order-id">Order ID</label><input id="track-order-id" name="order_id" value="${esc(id)}" placeholder="ORD-20261004-0001" autocomplete="off" required></div><div class="form-field"><label for="track-phone">Mobile number</label><input id="track-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="10-digit mobile number" pattern="(?:\\+91)?[6-9][0-9]{9}" title="Enter the mobile number used when placing the order" required></div><p id="track-error" class="form-error" role="alert">${esc(error)}</p><button class="btn btn-primary" type="submit">Find order status ↗</button></form><p class="tracking-privacy">For privacy, this lookup shows order progress and items only. Your delivery address and full phone number stay private.</p></section>`}
function trackingSummary(o){return `${crumb(["Order tracking"])}<section class="order-success tracking-result"><div class="success-mark">✓</div><h1>Order status</h1><p>Your latest order update is below.</p><div class="order-reference"><span>ORDER REFERENCE</span><strong>${esc(o.order_id)}</strong>${status(o.status)}</div><div class="order-detail-card"><div class="order-block"><h3>Your items</h3>${(o.items||[]).map(i=>`<div class="order-product"><span><strong>${esc(i.product_name)}</strong><small>${esc(i.variant)} · Qty ${i.quantity} · ${money(i.price*i.quantity)}</small></span></div>`).join("")}<div class="summary-row summary-total"><span>Order total</span><strong>${money(o.total)}</strong></div></div><div class="order-block"><h3>Payment</h3><p>${esc(o.payment_method=== "COD"?"Cash on Delivery":o.payment_method)}<br>${o.payment_method==="COD"?"Pay when your order is delivered.":""}</p></div><div class="order-block"><h3>Order details</h3><p>Placed ${esc(new Date(o.created_at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"}))}<br>Status: ${esc(o.status)}</p></div></div><p class="tracking-privacy">Your delivery address and full phone number are hidden on this lookup page.</p><div class="confirmation-actions"><a class="btn btn-outline" href="/track" data-link="/track">Track another order</a><a class="btn btn-primary" href="/shop" data-link="/shop">Continue shopping ↗</a></div></section>`}
async function ordersPage(){let saved=tokens();if(!saved.length){app.innerHTML=`${crumb(["My orders"])}<div class="catalog-heading"><div><h1>Your orders</h1><p>Orders placed on this device appear here.</p></div></div><div class="empty-state"><div class="empty-icon">▤</div><h2>No orders saved on this device</h2><p>If you have an order ID, you can still check its latest status using your checkout mobile number.</p><div class="confirmation-actions"><a class="btn btn-primary" href="/track" data-link="/track">Track an order</a><a class="btn btn-outline" href="/shop" data-link="/shop">Shop affordable finds</a></div></div>`;return}app.innerHTML=`${crumb(["My orders"])}<div class="store-status">Gathering your orders…</div>`;try{let all=await api("/api/my-orders",{method:"POST",body:JSON.stringify({tokens:saved})});if(path()!=="/orders")return;app.innerHTML=`${crumb(["My orders"])}<div class="catalog-heading"><div><h1>Your orders</h1><p>${all.length} ${all.length===1?"order":"orders"} in your history.</p></div><a class="text-link" href="/track" data-link="/track">Track with order ID ↗</a></div>${all.length?all.map(o=>`<a class="my-order-card" href="/track/${encodeURIComponent(o.order_id)}" data-link="/track/${encodeURIComponent(o.order_id)}"><div><h3>${esc(o.order_id)}</h3><small>${new Date(o.created_at).toLocaleDateString("en-IN")} · ${esc(o.payment_method)}</small></div><div class="my-order-products">${o.items.map(i=>`${esc(i.product_name)} × ${i.quantity}`).join(" · ")}</div>${status(o.status)}<span class="my-order-total">${money(o.total)}</span></a>`).join(""):`<div class="empty-state"><h2>No saved orders</h2><p>Use the order ID and checkout mobile number to find another order.</p><a class="btn btn-primary" href="/track" data-link="/track">Track an order</a></div>`}`}catch(e){app.innerHTML=`<div class="store-status">${esc(e.message)}</div>`}}
async function track(id){let cred=tokens().find(x=>x.id===id);if(!id){app.innerHTML=trackingLookup();return}if(!cred){app.innerHTML=trackingLookup(id);return}app.innerHTML=`${crumb(["Track an order"])}<div class="store-status">Loading your order…</div>`;try{let o=await api(`/api/order/${encodeURIComponent(id)}?token=${encodeURIComponent(cred.token)}`);if(path().startsWith("/track/"))app.innerHTML=confirmation(o,id)}catch(e){app.innerHTML=trackingLookup(id,e.message)}}
function policy(p){let data={"/privacy":["Privacy policy",`<p>We collect your name, phone number and delivery address to accept, fulfil and support your order. Order records are stored in the shop database and are visible to authorised store administrators for fulfilment and support.</p><h2>How we use information</h2><p>We use order details to process purchases, arrange delivery, answer questions and maintain order records. Your phone and address are not displayed publicly. An authorised admin manually places the corresponding supplier order.</p><h2>Payment details</h2><p>Cash on Delivery is currently available. Online payments remain disabled until a provider is configured. This site does not collect card or bank credentials.</p><h2>Your choices</h2><p>Contact the shop owner to request access, correction or removal of your information.</p>`],"/terms":["Terms & conditions",`<p>AMORA MART is an independent online shop. Product descriptions, prices and availability are provided for shopping information and may change.</p><h2>Orders</h2><p>Submitting an order records your purchase request. The initial status is “Order Received.” The store may contact you to clarify delivery details.</p><h2>Payment</h2><p>Cash on Delivery is currently offered; payment is due when delivery arrives. Online payment is not active.</p><h2>Product information</h2><p>Photos and descriptions help you choose. Small colour differences can occur between screens.</p>`],"/shipping":["Shipping policy",`<p>Orders are prepared after they are received and reviewed. Availability and timing depend on your location and delivery carrier.</p><h2>Delivery charges</h2><p>Delivery charges and free-delivery thresholds are shown at checkout. The store owner can edit these in admin settings.</p><h2>Order updates</h2><p>Use “My orders” on the device used to place the order to follow its status.</p>`],"/returns":["Returns & refunds",`<p>If something about an order needs attention, contact the shop using the owner-configured contact details.</p><h2>Tell us about an issue</h2><p>Include your order reference and a short description. The store owner will review and explain next steps based on the item and circumstances.</p><h2>Refunds</h2><p>For COD orders, any approved refund arrangement will be confirmed directly. This site does not process online refunds while online payments are disabled.</p>`],"/contact":["Contact AMORA MART",`<p>Questions about an order, product or delivery? We’re happy to help.</p><div id="contact-info" class="store-status">Contact details haven’t been added by the shop owner yet.</div><p style="margin-top:17px">Include your order reference when contacting us about an order.</p>`]}[p];return `${crumb([data[0]])}<div class="policy-copy"><span class="section-kicker">THE IMPORTANT DETAILS</span><h1>${esc(data[0])}</h1>${data[1]}<p class="policy-placeholder"><strong>Shop owner:</strong> Add your registered business name, contact email, support phone, return address and final policy details in Admin → Settings before launch.</p></div>`}

function title(t){document.title=`${t} · ${S.settings.shop_name||"AMORA MART"}`;let product=path().startsWith("/product/")?S.selected:null,description=product?`${product.name} — ${product.description}`:"Shop affordable everyday products at AMORA MART. Find budget-friendly home, kitchen, mobile, fashion and lifestyle essentials at wallet-friendly prices.";let d=document.querySelector('meta[name="description"]');if(d)d.content=description.slice(0,300);let og=document.querySelector('meta[property="og:title"]');if(og)og.content=document.title;let od=document.querySelector('meta[property="og:description"]');if(od)od.content=description.slice(0,300);let canonical=document.querySelector('link[rel="canonical"]');if(canonical)canonical.href=location.origin+location.pathname}
function hideAdmin(on){$("#storefront").style.display="";$(".mobile-nav").style.display=on?"none":"";document.body.classList.toggle("admin-body",on)}
async function render(){let p=path();if(p==="/admin"){hideAdmin(true);await renderAdmin();return}clearInterval(poll);hideAdmin(false);S.admin=false;if(p==="/"){app.innerHTML=home();title("Smart finds. Happier prices.")}else if(p==="/shop"){app.innerHTML=listing();title("Shop all finds")}else if(p.startsWith("/product/")){app.innerHTML=productPage(decodeURIComponent(p.slice(9)));title(S.selected?.name||"Product")}else if(p==="/cart"){app.innerHTML=cartPage();title("Your shopping bag")}else if(p==="/checkout"){app.innerHTML=checkout();title("Secure checkout");preview()}else if(p==="/orders"){title("My orders");await ordersPage()}else if(p==="/track"){title("Track your order");await track("")}else if(p.startsWith("/track/")){title("Track your order");await track(decodeURIComponent(p.slice(7)))}else if(["/privacy","/terms","/shipping","/returns","/contact"].includes(p)){app.innerHTML=policy(p);title(p.slice(1));let e=$("#contact-info");if(e)e.innerHTML=[S.settings.support_email?`<a href="mailto:${esc(S.settings.support_email)}">${esc(S.settings.support_email)}</a>`:"",S.settings.whatsapp_phone?`<a target="_blank" rel="noopener" href="https://wa.me/${esc(S.settings.whatsapp_phone.replace("+",""))}">WhatsApp ${esc(S.settings.whatsapp_phone)}</a>`:""].filter(Boolean).join(" · ")||"Contact details haven’t been added by the shop owner yet."}else{app.innerHTML=home();title("Smart finds. Happier prices.")}badge()}

const nav=[["dashboard","▦","Dashboard"],["orders","▤","Orders"],["products","▧","Products"],["customers","♙","Customers"],["categories","◫","Categories"],["payments","₹","Payments"],["analytics","⌁","Analytics"],["settings","⚙","Settings"]];
function logo(){return `<a href="/" class="brand" data-link="/"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M16 4.5c2.1 4.1 2.1 6.2 0 8.2-2.1-2-2.1-4.1 0-8.2Zm11.5 11.5c-4.1 2.1-6.2 2.1-8.2 0 2-2.1 4.1-2.1 8.2 0ZM16 27.5c-2.1-4.1-2.1-6.2 0-8.2 2.1 2 2.1 4.1 0 8.2ZM4.5 16c4.1-2.1 6.2-2.1 8.2 0-2 2.1-4.1 2.1-8.2 0Z"/><circle cx="16" cy="16" r="3.1"/></svg></span><span class="brand-type"><strong class="brand-name">${esc(S.settings.shop_name||"AMORA MART")}</strong><span class="brand-sub">STORE ADMIN</span></span></a>`}
function ah(title,desc,actions=""){return `<div class="admin-page-head"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${actions?`<div class="admin-page-actions">${actions}</div>`:""}</div>`}
function frame(content){let d=S.ad.dashboard||{};return `<div class="admin-shell"><header class="admin-topbar"><div class="admin-top-left">${logo()}<span class="admin-overline">STORE ADMIN</span></div><div class="admin-user"><span class="admin-user-avatar">A</span><span class="admin-user-copy"><strong>Shop administrator</strong><small>Private workspace</small></span><button data-action="logout">Sign out</button></div></header><div class="admin-layout"><aside class="admin-sidebar"><div class="admin-side-label">WORKSPACE</div><nav class="admin-nav-list">${nav.map(([id,icon,label])=>`<button class="admin-nav-btn ${S.view===id?"active":""}" data-action="view" data-view="${id}"><span class="admin-nav-icon">${icon}</span>${label}${id==="orders"&&d.new_orders?`<span class="admin-nav-count">${d.new_orders}</span>`:""}</button>`).join("")}</nav><div class="admin-side-note"><strong>Manual supplier fulfilment</strong>Copy customer and order details below, place each supplier order yourself, then update the order status.</div></aside><main class="admin-main">${content}</main></div></div>`}
function stat(label,value,icon,foot=""){return `<div class="admin-stat"><div class="admin-stat-top"><span class="admin-stat-label">${esc(label)}</span><span class="admin-stat-icon">${icon}</span></div><strong class="admin-stat-value">${esc(value)}</strong>${foot?`<div class="admin-stat-foot">${esc(foot)}</div>`:""}</div>`}
function recent(list){if(!list?.length)return `<div class="admin-empty">New orders will appear here once a customer places one.</div>`;return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Amount</th><th>Payment</th><th>Status</th></tr></thead><tbody>${list.map(o=>`<tr><td class="table-primary">${esc(o.order_id)}<div class="table-muted">${new Date(o.created_at).toLocaleDateString("en-IN")}</div></td><td><span class="table-primary">${esc(o.full_name)}</span><div class="table-muted">${esc(o.phone)}</div></td><td>${o.items.reduce((n,x)=>n+x.quantity,0)} item(s)</td><td class="table-primary">${money(o.total)}</td><td>${esc(o.payment_method)}</td><td>${status(o.status)}</td></tr>`).join("")}</tbody></table></div>`}
function dashboard(){let d=S.ad.dashboard||{};return `${ah("Good morning, admin","Here’s a little look at how your shop is doing.",`<button class="btn btn-outline btn-small" data-action="view" data-view="orders">View all orders ↗</button>`)}<div class="admin-stat-grid">${stat("Total orders",d.total_orders||0,"▤","All time")}${stat("New orders",d.new_orders||0,"✦","Ready for review")}${stat("Pending orders",d.pending_orders||0,"◷","In progress")}${stat("Confirmed",d.confirmed_orders||0,"✓","Ready to process")}${stat("Delivered",d.delivered_orders||0,"⌂","Completed orders")}${stat("Cancelled",d.cancelled_orders||0,"×","Cancelled orders")}${stat("Total sales",money(d.total_sales),"₹","Excludes cancelled orders")}</div><div class="admin-grid-2"><section class="admin-panel"><div class="admin-panel-head"><div><h2>Recent orders</h2><p>The latest little notes from customers.</p></div><button class="text-link" data-action="view" data-view="orders">View all ↗</button></div>${recent(d.recent_orders)}</section><section class="admin-panel"><div class="admin-panel-head"><div><h2>Best-selling finds</h2><p>What customers picked up the most.</p></div></div>${d.best_sellers?.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>Units</th><th>Sales</th></tr></thead><tbody>${d.best_sellers.map(p=>`<tr><td class="table-primary">${esc(p.name)}</td><td>${p.units}</td><td>${money(p.sales)}</td></tr>`).join("")}</tbody></table></div>`:`<div class="admin-empty">Best sellers will appear here.</div>`}<div class="admin-panel-head" style="margin-top:17px"><div><h2>Supplier workflow</h2><p>Orders are fulfilled manually.</p></div></div><p style="font-size:9px;color:#849087;line-height:1.8;margin:0">Copy customer and product information from an order, place the supplier order yourself, then update its status here.</p></section></div>`}
function orderCard(o){let address=addr(o.address),full=[`Order ID: ${o.order_id}`,"",`Customer:`,o.full_name,"",`Phone:`,o.phone,"",`Address:`,address,"",...o.items.flatMap(i=>[`Product:`,i.product_name,`Variant:`,i.variant,`Quantity:`,String(i.quantity),""]),`Total:`,money(o.total),"",`Payment:`,`Cash on Delivery`].join("\n"),customer=[o.full_name,o.phone,address].join("\n");return `<article class="order-detail-admin"><div class="order-detail-admin-top"><div><h3>${esc(o.order_id)} ${status(o.status)}</h3><small>${new Date(o.created_at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})} · ${esc(o.payment_method)} · Payment ${esc(o.payment_status)}</small></div><strong style="font:800 14px var(--display);color:var(--plum)">${money(o.total)}</strong></div><div class="order-admin-grid"><div class="admin-detail-block"><label>Customer</label><strong>${esc(o.full_name)}<br>${esc(o.phone)}${o.alternate_phone?`<br>Alt: ${esc(o.alternate_phone)}`:""}</strong><div class="admin-copy-row"><button class="copy-btn" data-action="copy" data-copy="${esc(customer)}">Copy customer details</button><button class="copy-btn" data-action="copy" data-copy="${esc(o.phone)}">Copy phone</button></div></div><div class="admin-detail-block address-block"><label>Full delivery address · PIN ${esc(o.address.pin)}</label><strong>${esc(address)}</strong><div class="admin-copy-row"><button class="copy-btn" data-action="copy" data-copy="${esc(address)}">Copy address</button><button class="copy-btn" data-action="copy" data-copy="${esc(full)}">Copy full order</button></div></div><div class="admin-detail-block"><label>Order summary · ${esc(o.payment_method)}</label><strong>Items ${money(o.subtotal)} · Delivery ${o.shipping?money(o.shipping):"Free"}<br>Discount ${money(o.discount)} · Total ${money(o.total)}<br>Payment status: ${esc(o.payment_status)}</strong></div></div><div class="admin-items">${o.items.map(i=>`<div class="admin-item-line"><strong>${esc(i.product_name)} <span style="font-weight:400;color:#929b95">(${esc(i.variant)})</span></strong><span>× ${i.quantity}</span><span>${money(i.price)} each</span></div>`).join("")}</div><div class="admin-order-bottom"><div class="admin-detail-block"><label>Private admin notes</label><textarea data-notes="${esc(o.order_id)}" placeholder="e.g. Supplier order placed.">${esc(o.notes||"")}</textarea></div><div class="admin-order-control"><select data-status="${esc(o.order_id)}">${STATUSES.map(s=>`<option ${o.status===s?"selected":""}>${esc(s)}</option>`).join("")}</select><button class="btn btn-primary" data-action="save-order" data-id="${esc(o.order_id)}">Save status & note</button></div></div></article>`}
function ordersView(){let list=S.ad.orders||[],filter=S.filter,q=S.search.toLowerCase(),items=list.filter(o=>(filter==="All"||o.status===filter)&&(!q||`${o.order_id} ${o.full_name} ${o.phone} ${addr(o.address)}`.toLowerCase().includes(q)));return `${ah("Orders",`${list.length} orders · Open an order for customer details and manual fulfilment tools.`)}<div class="admin-panel"><div class="order-toolbar"><label class="admin-search"><span>⌕</span><input id="order-search" placeholder="Search name, phone or order ID" value="${esc(S.search)}"></label><select id="status-filter" class="admin-select">${["All",...STATUSES].map(x=>`<option ${filter===x?"selected":""}>${esc(x)}</option>`).join("")}</select><button class="btn btn-outline btn-small" data-action="refresh">↻ Refresh</button></div>${items.length?items.map(orderCard).join(""):`<div class="admin-empty">No orders match this view yet.</div>`}</div>`}
function adminProductPhoto(p){let raw=String(p.images?.[0]||"").trim(),src=imgSafe(raw);return raw?`<div class="admin-product-image-wrap">${im(src,p.name,"admin-product-image")}<span class="admin-photo-fallback">Photo unavailable</span></div>`:`<div class="admin-product-placeholder"><span>▧</span><small>No product photo yet</small></div>`}
function productCardAdmin(p){return `<article class="admin-product-card">${adminProductPhoto(p)}<div class="admin-product-info"><div style="display:flex;justify-content:space-between;gap:8px"><h3>${esc(p.name)}</h3>${p.is_demo?`<span class="demo-flag">Demo</span>`:""}</div><p>${esc(p.category)} · ${money(p.price)} <s style="color:#a1aaa2">${money(p.mrp)}</s></p><p>${p.supplier_cost>0?`Internal only · Supplier ${money(p.supplier_cost)} · Est. gross margin ${money(p.price-p.supplier_cost)}`:"Internal only · Supplier cost not set · Margin unavailable"}</p><div class="admin-product-actions"><button class="btn btn-outline" data-action="edit-product" data-id="${p.id}">Edit</button><button class="btn btn-danger" data-action="del-product" data-id="${p.id}">Remove</button><span class="table-status ${p.active?"":"status-cancelled"}">${p.active?"Published":"Hidden"}</span></div></div></article>`}
function productsView(){let ps=S.ad.products||[];return `${ah("Products",`${ps.length} products · Add and update your catalogue here.`,`<button class="btn btn-primary btn-small" data-action="new-product">＋ Add product</button>`)}<p class="internal-callout"><strong>Internal only:</strong> supplier costs and estimated margins appear only in this signed-in admin view and are never shown in the public shop.</p>${ps.length?`<div class="admin-product-grid">${ps.map(productCardAdmin).join("")}</div>`:`<div class="admin-empty">Add your first product to get your shop started.</div>`}`}
function editor(p=null){p=p||{name:"",category:S.categories[0]?.name||"Everyday Essentials",description:"",mrp:"",price:"",supplier_cost:0,variants:[],specs:[],images:[],stock_status:"in_stock",cod:1,featured:0,bestseller:0,active:1,is_demo:0,id:""};return `${ah(p.id?"Edit product":"Add a product","Add details customers need to choose their next little favourite.")}<form id="product-editor" data-id="${esc(p.id)}" class="admin-panel product-form-panel"><div class="internal-callout">Supplier cost and estimated profit are private admin information.</div><div class="product-editor-grid"><div class="form-field full"><label>Product name *</label><input name="name" required maxlength="180" value="${esc(p.name)}" placeholder="Everyday storage basket"></div><div class="form-field"><label>Category *</label><select name="category">${S.categories.map(c=>`<option ${p.category===c.name?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div><div class="form-field"><label>Variants <span class="field-hint">(comma separated)</span></label><input name="variants" value="${esc((p.variants||[]).join(", "))}" placeholder="Small, Medium, Large"></div>${[["price","Selling price (₹)",p.price],["mrp","MRP (₹)",p.mrp],["supplier_cost","Supplier cost · admin only",p.supplier_cost]].map(([k,l,v])=>`<div class="form-field"><label>${l}</label><input name="${k}" type="number" min="${k==="supplier_cost"?0:1}" ${k==="supplier_cost"?"":"required"} value="${esc(v)}"></div>`).join("")}<div class="form-field"><label>Stock status</label><select name="stock_status"><option value="in_stock" ${p.stock_status==="in_stock"?"selected":""}>In stock</option><option value="out_of_stock" ${p.stock_status==="out_of_stock"?"selected":""}>Out of stock</option></select></div><div class="form-field full"><label>Description *</label><textarea name="description" required maxlength="6000" rows="4">${esc(p.description)}</textarea></div><div class="form-field full"><label>Specifications <span class="field-hint">(one per line)</span></label><textarea name="specs" rows="3">${esc((p.specs||[]).join("\n"))}</textarea></div><div class="form-field full"><label>Product photos · JPG / PNG / WebP / GIF · 5 MB max each</label><div class="upload-row"><input id="upload-files" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple><button type="button" class="btn btn-outline btn-small" data-action="upload">Upload photos</button></div><span class="field-hint">Choose photos and tap Upload photos to preview, or save the product to upload selected photos automatically.</span><div id="image-list" class="image-previews">${(p.images||[]).map((x,i)=>`<span class="image-preview">${im(x,"Product photo")}<button type="button" data-action="remove-image" data-index="${i}">×</button></span>`).join("")}</div><input type="hidden" name="images" value="${esc(JSON.stringify(p.images||[]))}"><label style="display:block;margin-top:9px">Or image URLs, one per line</label><textarea name="image_urls" rows="2">${esc((p.images||[]).filter(x=>/^https:\/\//.test(x)).join("\n"))}</textarea></div><div class="form-field full"><div class="checkbox-line">${[["cod","Cash on Delivery available"],["featured","Featured"],["bestseller","Best seller"],["active","Visible in shop"],["is_demo","Mark as demo content"]].map(([n,l])=>`<label><input name="${n}" type="checkbox" ${p[n]?"checked":""}> ${l}</label>`).join("")}</div></div></div><p id="product-error" class="admin-inline-error"></p><div class="admin-page-actions"><button type="button" class="btn btn-outline btn-small" data-action="view" data-view="products">Cancel</button><button class="btn btn-primary btn-small">Save product</button></div></form>`}

function customersView(){let cs=S.ad.customers||[];return `${ah("Customers",`${cs.length} customer records · Personal details are private to authorised admins.`)}<div class="internal-callout">Customer names and phone numbers are confidential. Only signed-in administrators can see this page.</div>${cs.length?`<div class="admin-customer-grid">${cs.map(c=>`<article class="admin-customer"><strong>${esc(c.full_name)}</strong><a href="tel:${esc(c.phone)}">${esc(c.phone)}</a><small>${c.orders} orders · Last order ${new Date(c.last_order).toLocaleDateString("en-IN")}</small><small>Completed order value ${money(c.spent)}</small></article>`).join("")}</div>`:`<div class="admin-empty">Customer details appear after orders arrive.</div>`}`}
function categoryForm(c={}){return `<form id="category-form" data-id="${esc(c.id||"")}" class="admin-panel"><div class="product-editor-grid"><div class="form-field"><label>Category name *</label><input name="name" required value="${esc(c.name||"")}"></div><div class="form-field"><label>Display order</label><input name="sort_order" type="number" value="${esc(c.sort_order??S.categories.length+1)}"></div><div class="form-field full"><label>Short description</label><input name="description" value="${esc(c.description||"")}"></div><div class="form-field full"><label>Image URL</label><input name="image" value="${esc(c.image||"")}"></div></div><p id="cat-error" class="admin-inline-error"></p><button type="button" class="btn btn-outline btn-small" data-action="cancel-cat">Cancel</button> <button class="btn btn-primary btn-small">Save category</button></form>`}
function categoriesView(){return `${ah("Categories","Organise your finds so shoppers can browse with ease.",`<button class="btn btn-primary btn-small" data-action="new-cat">＋ Add category</button>`)}<div class="admin-category-list">${(S.ad.categories||[]).map(c=>`<article class="admin-category-card">${im(c.image,c.name)}<div><strong>${esc(c.name)}</strong><small>${esc(c.description)}</small></div><button class="btn btn-outline btn-small" data-action="edit-cat" data-id="${c.id}">Edit</button><button class="btn btn-danger btn-small" data-action="del-cat" data-id="${c.id}">×</button></article>`).join("")}</div>${S.catEdit!==undefined?categoryForm(S.catEdit||{}):""}`}
function paymentsView(){let p=S.ad.payments||{};return `${ah("Payments","Payment collection and order payment statuses.")}<div class="admin-stat-grid">${stat("COD orders",p.cod_orders||0,"₹","Cash collected on delivery")}${stat("COD awaiting delivery",money(p.cod_pending),"◷","Payment pending from delivery")}${stat("Online payments","Disabled","○","Connect a real gateway before enabling")}</div><section class="admin-panel"><div class="admin-panel-head"><div><h2>Online payment setup</h2><p>Online payments are intentionally unavailable until configured.</p></div><span class="table-status status-processing">Not connected</span></div><p style="font-size:10px;color:#78857c;line-height:1.8">Choose a payment gateway account, add server-side API credentials to secure hosting, configure signed verification and webhook handling, then complete test transactions before enabling checkout. This store never simulates a successful payment.</p><div class="internal-callout">COD orders remain Payment status: Pending until collection is confirmed.</div></section>`}
function analyticsView(){let days=S.ad.analytics?.days||[];return `${ah("Analytics","A simple view of recent order activity.")}<section class="admin-panel"><div class="admin-panel-head"><div><h2>Recent days</h2><p>Sales exclude cancelled orders.</p></div></div>${days.length?`<table class="admin-table"><thead><tr><th>Date</th><th>Orders</th><th>Sales</th></tr></thead><tbody>${days.map(d=>`<tr><td>${new Date(d.day+"T00:00:00").toLocaleDateString("en-IN")}</td><td>${d.orders}</td><td>${money(d.sales)}</td></tr>`).join("")}</tbody></table>`:`<div class="admin-empty">Order activity appears here.</div>`}</section>`}
function settingsView(){let s=S.ad.settings||S.settings;return `${ah("Settings","Update your shop identity, support contact and delivery charges.")}<form id="settings-form" class="admin-panel product-form-panel"><div class="product-editor-grid"><div class="form-field full"><label>Shop name</label><input name="shop_name" required value="${esc(s.shop_name||"AMORA MART")}"></div><div class="form-field"><label>WhatsApp support number</label><input name="whatsapp_phone" type="tel" placeholder="Leave blank until configured" value="${esc(s.whatsapp_phone||"")}"><span class="field-hint">Use a real number with country code. Blank hides WhatsApp.</span></div><div class="form-field"><label>Support email</label><input name="support_email" type="email" placeholder="Leave blank until configured" value="${esc(s.support_email||"")}"></div><div class="form-field"><label>Delivery charge (₹)</label><input name="delivery_charge" type="number" min="0" value="${esc(s.delivery_charge??49)}"></div><div class="form-field"><label>Free delivery from (₹)</label><input name="free_delivery_threshold" type="number" min="0" value="${esc(s.free_delivery_threshold??999)}"></div></div><p class="field-hint" style="margin:15px 0">Business registration, return address and final customer policies still need to be added before launch.</p><p id="settings-error" class="admin-inline-error"></p><button class="btn btn-primary btn-small">Save settings</button></form><section class="admin-panel"><div class="admin-panel-head"><div><h2>Security & data</h2><p>Private admin access and customer data handling.</p></div></div><p style="font-size:9px;color:#7f8a81;line-height:1.8;margin:0">Admin passwords are stored as salted hashes. Customer details and supplier costs are only returned from authenticated admin endpoints. Change the admin password from the server, not the public site. Back up private <code>data/amora-mart.sqlite3</code> and uploaded product photos regularly.</p></section>`}
function content(){return ({dashboard,orders:ordersView,products:productsView,customers:customersView,categories:categoriesView,payments:paymentsView,analytics:analyticsView,settings:settingsView}[S.view]||dashboard)()}
async function load(view){let apiPath={dashboard:"dashboard",orders:"orders",products:"products",customers:"customers",categories:"categories",payments:"payments",analytics:"analytics",settings:"settings"}[view];let data=await api(`/api/admin/${apiPath}`);S.ad[view]=data;if(view==="categories"){S.categories=data} }
function login(error=""){app.innerHTML=`<div class="admin-login-wrap"><section class="admin-login">${logo()}<h1>Welcome back</h1><p>Sign in to your private AMORA MART dashboard.</p><form id="login-form"><div class="form-field"><label for="username">Admin username</label><input id="username" name="username" autocomplete="username" required></div><div class="form-field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><p id="login-error" class="login-error">${esc(error)}</p><button class="btn btn-primary">Sign in securely ↗</button></form><a href="/" data-link="/" class="admin-back">← Return to the shop</a></section></div>`}
let poll;async function renderAdmin(){clearInterval(poll);try{let s=await api("/api/admin/session");S.admin=s.authenticated;S.csrf=s.csrf||"";if(!S.admin){login();return}try{await load(S.view)}catch(e){app.innerHTML=frame(`<div class="admin-empty">${esc(e.message)}</div>`);return}app.innerHTML=frame(content());if(S.view==="dashboard")poll=setInterval(async()=>{if(path()!=="/admin"){clearInterval(poll);return}if(S.view!=="dashboard")return;try{await load("dashboard");app.innerHTML=frame(dashboard())}catch{}},45000)}catch(e){login(e.message)}}
async function adminGo(v){S.view=v;delete S.catEdit;try{await load(v);app.innerHTML=frame(content())}catch(e){toast(e.message,true);if(/sign in/i.test(e.message)){S.admin=false;login()}}}

async function uploadSelectedPhotos(form,button){let input=$("#upload-files",form),files=[...(input?.files||[])];if(!files.length)return;let images=JSON.parse(form.elements.images.value||"[]"),label=button?.textContent||"Upload photos";if(button){button.disabled=true;button.textContent="Uploading…"}try{for(let file of files){if(file.size>5*1024*1024)throw Error(`${file.name} is over 5 MB. Choose a smaller photo.`);if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type))throw Error(`${file.name} is not a supported photo format.`);let data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error(`Could not read ${file.name}.`));reader.readAsDataURL(file)});let saved=await api("/api/admin/upload",{method:"POST",body:JSON.stringify({data_url:data}),write:true});if(!saved.url||!saved.url.startsWith("/uploads/"))throw Error(`Could not save ${file.name}.`);if(!images.includes(saved.url))images.push(saved.url);form.elements.images.value=JSON.stringify(images);$("#image-list",form).innerHTML=images.map((src,i)=>`<span class="image-preview">${im(src,"Product photo")}<button type="button" data-action="remove-image" data-index="${i}" aria-label="Remove photo">×</button></span>`).join("")}input.value="";toast("Product photos uploaded.")}catch(error){input.value="";throw error}finally{if(button){button.disabled=false;button.textContent=label}}}
document.addEventListener("error",ev=>{let img=ev.target;if(!(img instanceof HTMLImageElement))return;let card=img.closest(".admin-product-image-wrap");if(card){img.hidden=true;card.classList.add("is-broken");return}if(!img.dataset.fallbackApplied){img.dataset.fallbackApplied="1";img.src="/assets/product-placeholder.svg"}},true);
document.addEventListener("click",async ev=>{let a=ev.target.closest("[data-link]");if(a){ev.preventDefault();go(a.dataset.link);return}let b=ev.target.closest("[data-action]");if(!b)return;let x=b.dataset.action;try{
 if(x==="add"||x==="buy"){let p=prod(b.dataset.id);add(p,p?.variants?.[0]);if(x==="buy")go("/checkout")}
 if(x==="fav"){let id=String(b.dataset.id);S.fav.has(id)?S.fav.delete(id):S.fav.add(id);localStorage.setItem("amora_favorites",JSON.stringify([...S.fav]));b.classList.toggle("active",S.fav.has(id));b.textContent=S.fav.has(id)?"♥":"♡"}
 if(x==="dadd"||x==="dbuy"){add(S.selected,S.variant,S.qty);if(x==="dbuy")go("/checkout")}
 if(x==="pqty"){S.qty=Math.max(1,Math.min(20,S.qty+Number(b.dataset.delta)));$("#detail-qty").textContent=S.qty}
 if(x==="variant"){S.variant=b.dataset.value;$$('.variant-option').forEach(y=>y.classList.toggle("selected",y===b))}
 if(x==="image"){let e=$("#detail-image img");if(e)e.src=imgSafe(b.dataset.src);$$('.detail-thumb').forEach(y=>y.classList.toggle("selected",y===b))}
 if(x==="pin"){let pin=$("#pin-check").value.trim();$("#pin-result").textContent=/^\d{6}$/.test(pin)?`Delivery availability for PIN ${pin} will be confirmed when we process your order.`:"Please enter a valid 6-digit PIN code."}
 if(x==="cqty"){let c=readCart(),line=c.find(y=>+y.product_id===+b.dataset.id&&y.variant===b.dataset.v);if(line){line.quantity+=Number(b.dataset.d);if(line.quantity<=0)c=c.filter(y=>y!==line);setCart(c);app.innerHTML=cartPage()}}
 if(x==="remove"){setCart(readCart().filter(y=>!(+y.product_id===+b.dataset.id&&y.variant===b.dataset.v)));app.innerHTML=cartPage()}
 if(x==="toggle-filter")$("#filter-panel")?.classList.toggle("open");
 if(x==="clear"){S.filters={category:"All",min:"",max:"",discount:false,available:true,rating:0};S.sort="popular";go("/shop")}
 if(x==="apply"){S.filters.min=$("#min-price")?.value||"";S.filters.max=$("#max-price")?.value||"";S.filters.discount=$("#discount-only")?.checked||false;S.filters.available=$("#available-only")?.checked||false;S.filters.rating=Number($("input[name=rating]:checked")?.value||0);S.filters.category=$("input[name=category]:checked")?.value||"All";let q=new URLSearchParams();if(S.filters.category!=="All")q.set("category",S.filters.category);if(S.filters.min)q.set("min",S.filters.min);if(S.filters.max)q.set("max",S.filters.max);if(S.filters.discount)q.set("deal","1");if(S.filters.rating)q.set("rating",S.filters.rating);go(`/shop${q.size?`?${q}`:""}`)}
 if(x==="copy"){await navigator.clipboard.writeText(b.dataset.copy||"");toast("Copied to clipboard.")}
 if(x==="view")await adminGo(b.dataset.view);
 if(x==="logout"){await api("/api/admin/logout",{method:"POST",body:"{}",write:true});S.admin=false;S.csrf="";login()}
 if(x==="refresh")await adminGo("orders");
 if(x==="save-order"){let id=b.dataset.id,sel=$(`[data-status="${CSS.escape(id)}"]`),notes=$(`[data-notes="${CSS.escape(id)}"]`);await api(`/api/admin/orders/${encodeURIComponent(id)}`,{method:"PUT",body:JSON.stringify({status:sel.value,notes:notes.value}),write:true});toast("Order details saved.");await adminGo("orders")}
 if(x==="new-product")app.innerHTML=frame(editor());
 if(x==="edit-product"){let p=(S.ad.products||[]).find(y=>+y.id===+b.dataset.id);app.innerHTML=frame(editor(p))}
 if(x==="del-product"){let p=(S.ad.products||[]).find(y=>+y.id===+b.dataset.id);if(p&&confirm(`Remove “${p.name}” from the shop?`)){await api(`/api/admin/products/${p.id}`,{method:"DELETE",write:true});toast("Product removed from shop.");await adminGo("products")}}
 if(x==="upload"){let form=$("#product-editor");if(!form)return;if(!$("#upload-files",form)?.files.length){toast("Choose one or more photos first.",true);return}await uploadSelectedPhotos(form,b)}
 if(x==="remove-image"){let f=$("#product-editor"),images=JSON.parse(f.elements.images.value||"[]");images.splice(+b.dataset.index,1);f.elements.images.value=JSON.stringify(images);$("#image-list",f).innerHTML=images.map((src,i)=>`<span class="image-preview">${im(src,"Product photo")}<button type="button" data-action="remove-image" data-index="${i}" aria-label="Remove photo">×</button></span>`).join("")}
 if(x==="new-cat"){S.catEdit={};app.innerHTML=frame(categoriesView())}
 if(x==="edit-cat"){S.catEdit=(S.ad.categories||[]).find(y=>+y.id===+b.dataset.id);app.innerHTML=frame(categoriesView())}
 if(x==="cancel-cat"){delete S.catEdit;app.innerHTML=frame(categoriesView())}
 if(x==="del-cat"){let c=(S.ad.categories||[]).find(y=>+y.id===+b.dataset.id);if(c&&confirm(`Remove category “${c.name}”? Its products will be uncategorised.`)){await api(`/api/admin/categories/${c.id}`,{method:"DELETE",write:true});toast("Category removed.");await adminGo("categories")}}
}catch(e){toast(e.message,true)}});

document.addEventListener("input",ev=>{if(ev.target.closest("#checkout-form"))preview();if(ev.target.id==="order-search"){S.search=ev.target.value;let pos=ev.target.selectionStart;app.innerHTML=frame(ordersView());let f=$("#order-search");f?.focus();f?.setSelectionRange(pos,pos)}});
document.addEventListener("change",ev=>{if(ev.target.id==="sort-products"){S.sort=ev.target.value;let q=new URLSearchParams(location.search);q.set("sort",S.sort);go(`/shop?${q}`)}if(ev.target.name==="category"&&ev.target.type==="radio"){S.filters.category=ev.target.value;if(!$("#filter-panel")?.classList.contains("open")){let q=new URLSearchParams();if(S.filters.category!=="All")q.set("category",S.filters.category);go(`/shop${q.size?`?${q}`:""}`)}}if(ev.target.id==="status-filter"){S.filter=ev.target.value;app.innerHTML=frame(ordersView())}if(ev.target.name==="rating")S.filters.rating=Number(ev.target.value)});

function orderPayload(form){let d=Object.fromEntries(new FormData(form).entries());return{full_name:d.full_name.trim(),phone:d.phone.trim(),alternate_phone:(d.alternate_phone||"").trim(),address:{house:d.house.trim(),street:d.street.trim(),locality:d.locality.trim(),landmark:(d.landmark||"").trim(),city:d.city.trim(),district:d.district.trim(),state:d.state.trim(),pin:d.pin.trim()},payment_method:"COD",confirmed_details:$("#confirm-details").checked,items:resolved().map(x=>({product_id:+x.product_id,variant:x.variant,quantity:x.quantity}))}}
document.addEventListener("submit",async ev=>{let f=ev.target;try{
 if(f.id==="search-form"){ev.preventDefault();let q=$("#search-input").value.trim(),u=new URLSearchParams();if(q)u.set("q",q);go(`/shop${u.size?`?${u}`:""}`)}
 if(f.id==="track-form"){ev.preventDefault();if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f).entries()),b=f.querySelector('button[type="submit"]');b.disabled=true;b.textContent="Looking up your order…";$("#track-error").textContent="";try{let o=await api("/api/track-order",{method:"POST",body:JSON.stringify(d)});app.innerHTML=trackingSummary(o);title("Order status");scrollTo({top:0,behavior:"smooth"})}catch(e){$("#track-error").textContent=e.message;b.disabled=false;b.textContent="Find order status ↗"}}
 if(f.id==="checkout-form"){ev.preventDefault();if(!f.reportValidity())return;let d=orderPayload(f);if(!d.confirmed_details){$("#checkout-error").textContent="Please confirm your delivery details are correct.";return}let b=$("#place-order");b.disabled=true;b.textContent="Placing your order…";try{let r=await api("/api/orders",{method:"POST",body:JSON.stringify(d)}),o=r.order,s=tokens().filter(x=>x.id!==o.order_id);s.unshift({id:o.order_id,token:r.access_token});localStorage.setItem("amora_orders",JSON.stringify(s.slice(0,30)));setCart([]);S.draft={};history.pushState({},"",`/track/${encodeURIComponent(o.order_id)}`);app.innerHTML=confirmation(o,o.order_id);title("Order confirmed");scrollTo({top:0,behavior:"smooth"})}catch(e){$("#checkout-error").textContent=e.message;b.disabled=false;b.textContent="Place order ↗"}}
 if(f.id==="login-form"){ev.preventDefault();let d=Object.fromEntries(new FormData(f).entries());try{let r=await api("/api/admin/login",{method:"POST",body:JSON.stringify(d)});S.admin=true;S.csrf=r.csrf;S.view="dashboard";await renderAdmin()}catch(e){$("#login-error").textContent=e.message;$("#password").value=""}}
 if(f.id==="product-editor"){ev.preventDefault();await uploadSelectedPhotos(f,$("[data-action=upload]",f));let d=new FormData(f),images=JSON.parse(d.get("images")||"[]"),urls=String(d.get("image_urls")||"").split(/\r?\n/).map(x=>x.trim()).filter(x=>/^https:\/\//.test(x)),payload={name:d.get("name"),category:d.get("category"),description:d.get("description"),price:+d.get("price"),mrp:+d.get("mrp"),supplier_cost:+(d.get("supplier_cost")||0),variants:String(d.get("variants")||"").split(",").map(x=>x.trim()).filter(Boolean),specs:String(d.get("specs")||"").split(/\r?\n/).map(x=>x.trim()).filter(Boolean),images:[...new Set([...images,...urls])],stock_status:d.get("stock_status"),cod:d.has("cod"),featured:d.has("featured"),bestseller:d.has("bestseller"),active:d.has("active"),is_demo:d.has("is_demo")};try{let id=f.dataset.id;await api(id?`/api/admin/products/${id}`:"/api/admin/products",{method:id?"PUT":"POST",body:JSON.stringify(payload),write:true});toast("Product saved.");await adminGo("products")}catch(e){$("#product-error").textContent=e.message}}
 if(f.id==="category-form"){ev.preventDefault();let payload=Object.fromEntries(new FormData(f).entries()),id=f.dataset.id;try{await api(id?`/api/admin/categories/${id}`:"/api/admin/categories",{method:id?"PUT":"POST",body:JSON.stringify(payload),write:true});delete S.catEdit;toast("Category saved.");await adminGo("categories")}catch(e){$("#cat-error").textContent=e.message}}
 if(f.id==="settings-form"){ev.preventDefault();let d=Object.fromEntries(new FormData(f).entries());try{await api("/api/admin/settings",{method:"PUT",body:JSON.stringify(d),write:true});S.settings=await api("/api/settings");let footerName=$("#footer-shop-name");if(footerName)footerName.textContent=S.settings.shop_name||"AMORA MART";let w=$("#whatsapp-support");if(S.settings.whatsapp_phone){w.href=`https://wa.me/${encodeURIComponent(S.settings.whatsapp_phone.replace("+",""))}`;w.hidden=false}else w.hidden=true;$$(".brand-name").forEach(e=>e.textContent=(S.settings.shop_name||"AMORA MART").split(/\s+/)[0]);$$(".brand-sub").forEach(e=>e.textContent=(S.settings.shop_name||"AMORA MART").split(/\s+/).slice(1).join(" "));toast("Shop settings saved.");await adminGo("settings")}catch(e){$("#settings-error").textContent=e.message}}
}catch(e){toast(e.message,true)}});
window.addEventListener("popstate",render);
async function boot(){$("#footer-year").textContent=new Date().getFullYear();badge();try{let [ps,cs,s]=await Promise.all([api("/api/products"),api("/api/categories"),api("/api/settings")]);S.products=ps;S.categories=cs;S.settings=s;let footerName=$("#footer-shop-name");if(footerName)footerName.textContent=s.shop_name||"AMORA MART";let w=$("#whatsapp-support");if(s.whatsapp_phone){w.href=`https://wa.me/${encodeURIComponent(s.whatsapp_phone.replace("+",""))}`;w.hidden=false}$$(".brand-name").forEach(e=>e.textContent=(s.shop_name||"AMORA MART").split(/\s+/)[0]);$$(".brand-sub").forEach(e=>e.textContent=(s.shop_name||"AMORA MART").split(/\s+/).slice(1).join(" "));await render()}catch(e){app.innerHTML=`<div class="empty-state" style="margin-top:30px"><div class="empty-icon">⌁</div><h2>We’re getting the shop ready</h2><p>${esc(e.message)} Start the AMORA MART server and refresh this page.</p></div>`}}
boot();


